  add <name> <price> [--every month|week|year] [--since YYYY-MM-DD]
  list
  total
  renewals [--within <days>]
  export
  remove <name>

options for every command: --file <path>, --today YYYY-MM-DD`;

function die(message, code = 1) {
  process.stderr.write(`subtrack: ${message}\n`);
  process.exit(code);
}

// --every month|week|year (monthly/weekly/yearly work too)
const EVERY = { month: CYCLE.MONTH, monthly: CYCLE.MONTH, week: CYCLE.WEEK, weekly: CYCLE.WEEK, year: CYCLE.YEAR, yearly: CYCLE.YEAR };

function cycleFlag(value = 'month') {
  const cycle = EVERY[value.toLowerCase()];
  if (!cycle) die(`--every must be month, week, or year, got "${value}"`, 2);
  return cycle;
}

